## Appendix: `permission_harness_prefix.rs`

```rust
use std::collections::BTreeMap;
use std::future::Future;
use std::sync::Arc;
use std::task::{Context, Poll, Wake, Waker};

#[macro_export]
macro_rules! anyhow {
	($($arg:tt)*) => { format!($($arg)*) };
}

mod anyhow {
	pub use crate::anyhow;
}

#[derive(Clone, Debug, PartialEq, Eq)]
enum Part {
	Field(&'static str),
	All,
	Index(usize),
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct Idiom(Vec<Part>);

#[derive(Clone, Debug, PartialEq, Eq)]
enum Value {
	Object(BTreeMap<String, Value>),
	Array(Vec<Value>),
	Number(i64),
	Text(String),
}

impl Value {
	fn each(&self, idiom: &[Part]) -> Vec<Idiom> {
		let Value::Object(root) = self else { return Vec::new() };
		let Some(Value::Array(items)) = root.get("items") else { return Vec::new() };
		match idiom {
			[Part::Field("items"), Part::All] => items
				.iter()
				.enumerate()
				.map(|(index, _)| Idiom(vec![Part::Field("items"), Part::Index(index)]))
				.collect(),
			[Part::Field("items"), Part::All, Part::Field("secret")] => items
				.iter()
				.enumerate()
				.filter(|(_, item)| matches!(item, Value::Object(map) if map.contains_key("secret")))
				.map(|(index, _)| Idiom(vec![Part::Field("items"), Part::Index(index), Part::Field("secret")]))
				.collect(),
			_ => Vec::new(),
		}
	}

	fn pick(&self, path: &[Part]) -> Value {
		let Value::Object(root) = self else { panic!("row is not an object") };
		let Value::Array(items) = root.get("items").expect("items field") else { panic!("items is not an array") };
		let Part::Index(index) = path[1] else { panic!("path index missing") };
		let item = items.get(index).expect("original index exists");
		if path.len() == 2 {
			return item.clone();
		}
		let Value::Object(map) = item else { panic!("item is not an object") };
		map.get("secret").expect("secret field").clone()
	}

	fn cut(&mut self, path: &[Part]) {
		let Value::Object(root) = self else { return };
		let Some(Value::Array(items)) = root.get_mut("items") else { return };
		let Part::Index(index) = path[1] else { return };
		if path.len() == 2 {
			if index < items.len() {
				items.remove(index);
			}
			return;
		}
		if let Some(Value::Object(map)) = items.get_mut(index) {
			map.remove("secret");
		}
	}
}

#[derive(Clone, Debug)]
enum Condition {
	EvenElement,
	AllowAll,
	SecretS1,
}

#[derive(Clone, Debug)]
enum PhysicalPermission {
	Allow,
	Deny,
	Conditional(Condition),
}

struct ExecutionContext;

struct FieldState {
	field_permissions: Vec<(Idiom, PhysicalPermission)>,
}

#[derive(Debug)]
enum ControlFlow {
	Err(String),
	Return(Value),
}

async fn check_permission_for_value(
	permission: &PhysicalPermission,
	_original: &Value,
	field_value: Option<&Value>,
	_ctx: &ExecutionContext,
) -> Result<bool, String> {
	let value = field_value.ok_or_else(|| "missing field value".to_owned())?;
	match permission {
		PhysicalPermission::Allow => Ok(true),
		PhysicalPermission::Deny => Ok(false),
		PhysicalPermission::Conditional(Condition::AllowAll) => Ok(true),
		PhysicalPermission::Conditional(Condition::SecretS1) => {
			Ok(matches!(value, Value::Text(text) if text == "s1"))
		}
		PhysicalPermission::Conditional(Condition::EvenElement) => {
			let Value::Object(map) = value else { return Ok(false) };
			Ok(matches!(map.get("n"), Some(Value::Number(n)) if n % 2 == 0))
		}
	}
}
```

## Appendix: `permission_harness_suffix.rs`

```rust
struct NoopWake;

impl Wake for NoopWake {
	fn wake(self: Arc<Self>) {}
}

fn block_on<F: Future>(future: F) -> F::Output {
	let waker = Waker::from(Arc::new(NoopWake));
	let mut context = Context::from_waker(&waker);
	let mut future = std::pin::pin!(future);
	loop {
		match future.as_mut().poll(&mut context) {
			Poll::Ready(output) => return output,
			Poll::Pending => std::thread::yield_now(),
		}
	}
}

fn item(n: i64, secret: &str) -> Value {
	Value::Object(BTreeMap::from([
		("n".to_owned(), Value::Number(n)),
		("secret".to_owned(), Value::Text(secret.to_owned())),
	]))
}

fn row() -> Value {
	Value::Object(BTreeMap::from([(
		"items".to_owned(),
		Value::Array(vec![item(0, "s0"), item(1, "s1"), item(2, "s2"), item(3, "s3")]),
	)]))
}

fn fields(parent: Condition) -> FieldState {
	FieldState {
		field_permissions: vec![
			(
				Idiom(vec![Part::Field("items"), Part::All]),
				PhysicalPermission::Conditional(parent),
			),
			(
				Idiom(vec![Part::Field("items"), Part::All, Part::Field("secret")]),
				PhysicalPermission::Conditional(Condition::SecretS1),
			),
		],
	}
}

fn observed_items(value: &Value) -> Vec<(i64, Option<String>)> {
	let Value::Object(root) = value else { panic!("result is not an object") };
	let Some(Value::Array(items)) = root.get("items") else { panic!("result has no items") };
	items
		.iter()
		.map(|item| {
			let Value::Object(map) = item else { panic!("item is not an object") };
			let Some(Value::Number(n)) = map.get("n") else { panic!("item has no n") };
			let secret = match map.get("secret") {
				Some(Value::Text(text)) => Some(text.clone()),
				None => None,
				_ => panic!("secret is not text"),
			};
			(*n, secret)
		})
		.collect()
}

fn main() {
	let mode = std::env::args().nth(1).expect("missing mode");
	let parent = if mode == "main" { Condition::EvenElement } else { Condition::AllowAll };
	let mut value = row();
	block_on(filter_fields_by_permission(&ExecutionContext, &fields(parent), &mut value))
		.expect("target function returned an error");
	let observed = observed_items(&value);
	if mode == "main" {
		assert_eq!(observed, vec![(0, None), (2, Some("s2".to_owned()))]);
		println!("VIOLATION:shifted-n2-retained-denied-s2");
	} else {
		assert_eq!(
			observed,
			vec![(0, None), (1, Some("s1".to_owned())), (2, None), (3, None)]
		);
		println!("CONTROL:stable-indices-only-allow-s1");
	}
}
```

### Patches

A patch has been created that cuts overlapping array field-permissions by element identity, so a wildcard field permission no longer drifts across array indexes.

- Version 4.0.0 and later are not affected by this issue.

